<template>
  <div class="app-container carriers">
    <div class="heading"><div><h2>{{title}}</h2><p>{{description}}</p></div><el-tag v-if="mapping&&system==='CHANNEL'" type="info">当前接入：天猫</el-tag></div>
    <el-alert v-if="error" :title="error" type="error" show-icon :closable="false"/>
    <el-alert v-if="$route.query.from_todo||$route.query.from_check" title="已带入原业务用途、快递和适用范围。保存配置后请检查修复结果，再继续未完成的业务步骤。" type="info" show-icon :closable="false"/>
    <el-button v-if="$route.query.from_todo" type="text" @click="backToTodo">返回原关联待办</el-button>
    <el-tabs v-if="mapping" v-model="section" @tab-click="reset"><el-tab-pane label="标准快递关联" name="mapping"/><el-tab-pane :label="terms.list" name="directory"/><el-tab-pane label="清单更新记录" name="sync"/></el-tabs>
    <el-radio-group v-if="kind==='capability'" v-model="query.flow" size="small" class="flow-tabs" @change="reset"><el-radio-button label="OUTBOUND">发货能力</el-radio-button><el-radio-button label="INBOUND">收货能力</el-radio-button></el-radio-group>
    <div class="workspace-tools">
      <div class="toolbar">
        <el-input v-model="query.keyword" clearable :placeholder="kind==='todo'?'搜索业务单号':kind==='standard'?'搜索名称、OMS 编码或别名':'搜索快递名称或编码'" @keyup.enter.native="reset"/>
        <el-select v-if="mapping" v-model="query.purpose" clearable placeholder="全部业务用途" @change="reset"><el-option v-for="p in purposes" :key="p" :value="p" :label="labels[p]"/></el-select>
        <el-select v-if="!['todo','sync'].includes(type)" v-model="query.enabled" clearable placeholder="全部配置状态" @change="reset"><el-option label="已启用" value="1"/><el-option label="已停用" value="0"/></el-select>
        <el-select v-if="type==='directory'" v-model="query.association_state" clearable placeholder="全部关联状态" @change="reset"><el-option v-for="(label,key) in associations" :key="key" :label="label" :value="key"/></el-select>
        <el-select v-if="kind==='todo'" v-model="query.state" clearable placeholder="全部处理进度" @change="reset"><el-option v-for="(label,key) in todoStates" :key="key" :label="label" :value="key"/></el-select>
        <el-select v-if="kind==='todo'" v-model="query.business_type" clearable placeholder="全部业务类型" @change="reset"><el-option v-for="(label,key) in businessLabels" :key="key" :label="label" :value="key"/></el-select>
        <el-button size="small" @click="reset">查询</el-button><el-button size="small" @click="clearFilters">重置</el-button>
      </div>
      <div class="page-actions">
        <el-button v-if="canEdit&&!['todo','sync'].includes(type)" type="primary" size="small" @click="edit()">{{type==='standard'?'新增标准快递':type==='capability'?'新增仓库服务':type==='directory'?'补录'+terms.item:'关联标准快递'}}</el-button>
        <el-button v-if="canEdit&&type==='directory'" size="small" @click="openImport">导入快递清单</el-button>
        <el-button size="small" @click="$refs.verification.open(contextSeed())">场景核验</el-button>
        <el-dropdown trigger="click" @command="moreAction"><el-button size="small">更多<i class="el-icon-arrow-down el-icon--right"/></el-button><el-dropdown-menu slot="dropdown"><el-dropdown-item command="refresh">刷新列表</el-dropdown-item><el-dropdown-item v-if="canEdit&&mapping" command="sync">同步快递清单</el-dropdown-item><el-dropdown-item v-if="canAudit" command="audit">操作记录</el-dropdown-item></el-dropdown-menu></el-dropdown>
      </div>
    </div>
    <div v-if="mapping||kind==='capability'" class="scope-filters">
      <template v-if="system==='WMS'"><el-select v-model="query.connection_id" clearable filterable placeholder="全部 WMS 连接" @change="filterConnection"><el-option v-for="c in metadata.connections||[]" :key="c.id" :value="String(c.id)" :label="c.name"/></el-select><el-select v-model="query.owner_code" clearable filterable :disabled="!query.connection_id" placeholder="全部货主" @change="filterOwner"><el-option v-for="o in filterOwners" :key="o.owner_code" :value="o.owner_code" :label="o.owner_name||o.owner_code"/></el-select><el-select v-model="query.real_store_code" clearable filterable :disabled="!query.owner_code" placeholder="全部实体仓" @change="reset"><el-option v-for="w in filterStores" :key="w.real_store_code" :value="w.real_store_code" :label="w.real_store_name||w.real_store_code"/></el-select></template>
      <el-select v-else v-model="query.shop_id" clearable filterable placeholder="全部天猫店铺" @change="reset"><el-option v-for="shop in metadata.shops||[]" v-show="['TM','TMALL'].includes(shop.channel_type)" :key="shop.channel_id" :value="String(shop.channel_id)" :label="shop.channel_name"/></el-select>
      <el-tag v-if="query.directory_id" closable @close="query.directory_id='';reset()">仅看所选清单条目的关联</el-tag><el-tag v-if="query.external_code" closable @close="query.external_code='';reset()">原始编码：{{query.external_code}}</el-tag><el-tag v-if="query.standard_id" closable @close="query.standard_id='';reset()">已限定标准快递</el-tag>
    </div>
    <div v-if="type==='directory'&&selectedDirectories.length" class="selection-bar">已选 {{selectedDirectories.length}} 条快递<el-button v-if="canEdit" size="small" type="primary" :disabled="selectedDirectories.length>100" @click="$refs.batch.open(selectedDirectories)">批量关联标准快递</el-button><span class="hint">同一用途与适用范围内每批最多100条</span></div>
    <p class="table-caption">共 {{total}} 条{{type==='mapping'?'关联':type==='directory'?'快递':''}}<span v-if="type==='mapping'"> · 配置启用与场景检查分别展示；检查结果仅适用于所选范围。</span></p>
    <el-table :key="type" v-loading="loading" :data="rows" row-key="id" @selection-change="selectedDirectories=$event" :empty-text="loading?'正在读取…':error?'查询失败，请重试':'当前条件下暂无记录，请调整筛选或新增配置'" size="small">
      <el-table-column v-if="type==='directory'&&canEdit" type="selection" width="45"/>
      <el-table-column v-if="kind==='standard'||['mapping','capability'].includes(type)" label="标准快递" min-width="185"><template slot-scope="{row}"><strong class="scope-text">{{row.standard_name}}</strong><carrier-code :value="row.standard_code" label="OMS 标准编码"/><p v-if="kind==='standard'" class="hint">{{(row.aliases||[]).join('、')||'暂无搜索别名'}}</p></template></el-table-column>
      <el-table-column v-if="['mapping','directory'].includes(type)" :label="terms.item" min-width="200"><template slot-scope="{row}"><span :title="row.external_name" class="truncate">{{row.external_name}}</span><carrier-code :value="row.external_code" :label="terms.code"/><el-tag v-if="row.is_default&&carrierMappingRule(row)&&carrierMappingRule(row).direction==='OUT'" size="mini" type="info">{{system==='CHANNEL'?'平台提交首选':'仓库下发首选'}}</el-tag></template></el-table-column>
      <el-table-column v-if="mapping||type==='capability'" label="业务用途" width="165"><template slot-scope="{row}">{{labels[row.purpose]||(row.flow==='INBOUND'?'仓库收货':row.flow==='OUTBOUND'?'仓库发货':'用途待核实')}}</template></el-table-column>
      <el-table-column v-if="mapping||type==='capability'" label="适用范围" min-width="215"><template slot-scope="{row}"><span :title="scopeName(row)" class="scope-text">{{scopeName(row)}}</span><p v-if="system==='WMS'&&['mapping','capability'].includes(type)" class="hint">{{row.product_code?'运输产品：'+row.product_code:'通用匹配'}}</p></template></el-table-column>
      <el-table-column v-if="type==='directory'" label="关联状态" width="150"><template slot-scope="{row}"><el-tag size="small" :type="row.association_state==='UNLINKED'?'warning':row.association_state==='DISABLED'?'danger':'info'">{{associations[row.association_state]}}</el-tag><p v-if="Number(row.mapping_count)" class="hint">{{row.mapping_count}} 条关联</p></template></el-table-column>
      <el-table-column v-if="type==='capability'" label="服务范围" min-width="190"><template slot-scope="{row}"><el-popover trigger="hover" width="330"><p>{{delivery(row,true)}}</p><span slot="reference">{{delivery(row)}}</span></el-popover></template></el-table-column>
      <el-table-column v-if="kind==='todo'" label="业务单据" min-width="240"><template slot-scope="{row}"><el-link type="primary" @click="openBusiness(row)">{{row.business_sn}}</el-link><p class="hint">{{businessLabels[row.business_type]||row.business_type}} · {{actionLabels[row.blocked_action]||'处理物流'}} · 出现 {{row.occurrences}} 次</p></template></el-table-column>
      <el-table-column v-if="kind==='todo'" label="问题与处理进度" min-width="285"><template slot-scope="{row}"><el-tag size="small" :type="row.state==='COMPLETED'?'success':row.state==='READY'?'info':'warning'">{{todoStates[row.state]}}</el-tag><p>{{row.reason}}</p></template></el-table-column>
      <el-table-column v-if="kind==='todo'" label="原始快递与适用范围" min-width="240"><template slot-scope="{row}"><carrier-code v-if="todoContext(row).external_code" :value="todoContext(row).external_code" label="原始快递编码"/><span class="scope-text">{{scopeName(todoContext(row))}}</span><p class="hint">{{labels[todoContext(row).purpose]}}</p></template></el-table-column>
      <el-table-column v-if="type==='sync'" label="清单更新结果" min-width="300"><template slot-scope="{row}"><el-tag size="small">{{syncStates[row.state]||row.state}}</el-tag><p>{{syncMessage(row)}}</p><el-button v-if="row.state==='SUCCESS'" type="text" @click="showSync(row)">查看差异并确认导入</el-button></template></el-table-column>
      <el-table-column v-if="!['todo','sync'].includes(type)" label="配置状态" width="130"><template slot-scope="{row}"><el-tag size="small" type="info">{{Number(row.enabled)===1?'已启用':'已停用'}}</el-tag><p v-if="!Number(row.enabled)" class="hint">{{row.disabled_reason}}</p><p v-if="type==='mapping'&&(Number(row.standard_enabled)===0||Number(row.directory_enabled)===0)" class="warning">标准快递或清单已停用</p><el-popover v-if="row.evidence" trigger="click" width="360"><p class="source-proof">{{row.evidence}}</p><el-button slot="reference" type="text" size="mini">查看来源说明</el-button></el-popover></template></el-table-column>
      <el-table-column v-if="type==='mapping'" label="指定场景检查" width="150"><template slot-scope="{row}"><el-popover v-if="scenarioChecks[row.id]" trigger="click" width="380"><p>{{scenarioChecks[row.id].scenario}} · {{scenarioChecks[row.id].scope}}</p><p>{{scenarioChecks[row.id].time}} · 仅为本次检查结果</p><el-button slot="reference" type="text">{{scenarioChecks[row.id].available?'本次场景通过':'本次场景有问题'}}</el-button></el-popover><span v-else class="hint">未检查</span></template></el-table-column>
      <el-table-column label="最近变更" width="155"><template slot-scope="{row}">{{row.update_time||row.finish_time||row.create_time}}<p class="hint">{{row.updated_by||row.actor}}</p></template></el-table-column>
      <el-table-column label="操作" fixed="right" :width="type==='mapping'?190:kind==='todo'?230:190"><template slot-scope="{row}">
        <template v-if="kind==='todo'"><el-button v-if="row.state==='OPEN'" type="text" @click="repair(row)">去修复配置</el-button><el-button v-if="row.state!=='COMPLETED'" v-hasPermi="['common:carrier:todoHandle']" type="text" :disabled="busy" @click="todoAction(row,'revalidate')">检查修复结果</el-button><el-button v-if="row.state==='READY'" v-hasPermi="['common:carrier:todoHandle']" type="text" :disabled="busy" @click="todoAction(row,'retry')">继续未完成步骤</el-button><el-button type="text" @click="configure(row)">详情</el-button></template>
        <template v-else-if="type==='directory'"><el-button v-if="row.association_state==='UNLINKED'&&canEdit" type="text" @click="associate(row)">关联标准快递</el-button><el-button v-if="row.association_state!=='UNLINKED'" type="text" @click="viewLinks(row)">查看关联</el-button><el-button v-if="canEdit" type="text" @click="edit(row)">编辑清单</el-button></template>
        <template v-else-if="type!=='sync'"><el-button v-if="canEdit" type="text" @click="edit(row)">编辑</el-button><el-button v-if="type==='mapping'" type="text" @click="$refs.verification.open(row)">检查场景</el-button><el-button v-if="canAudit" type="text" @click="$refs.audit.open(type,row.id)">记录</el-button></template>
      </template></el-table-column>
    </el-table>
    <pagination v-show="total>0" :total="total" :page.sync="query.pageNum" :limit.sync="query.pageSize" @pagination="load"/>
    <el-dialog :title="editorTitle" :visible.sync="editor" width="760px" append-to-body :close-on-click-modal="false" :before-close="closeEditor">
      <el-alert v-if="formError||preferredError" :title="formError||preferredError" type="error" :closable="false" show-icon /><el-button v-if="preferredError" type="text" @click="loadPreferred">重新核对提交或下发候选</el-button>
      <el-form label-width="160px" :disabled="busy" class="editor">
        <template v-if="type==='standard'"><el-form-item label="OMS 标准编码" required><el-input v-model="form.standard_code" :disabled="!!form.id" maxlength="64" placeholder="创建后固定，如 SF_EXPRESS" /></el-form-item><el-form-item label="标准快递名称" required><el-input v-model="form.standard_name" maxlength="100" placeholder="填写承运商名称，例如顺丰速运" /></el-form-item><el-form-item label="分类"><el-select v-model="form.category"><el-option v-for="(v,k) in categories" :key="k" :label="v" :value="k" /></el-select></el-form-item><el-form-item label="搜索别名"><el-select v-model="form.aliases" multiple filterable allow-create default-first-option placeholder="输入别名后按回车；仅用于搜索" /></el-form-item><el-alert title="标准快递可独立启用。平台、仓库快递关联及仓库服务能力在对应页面分别配置。" type="info" :closable="false" /></template>
        <template v-else><h3 class="form-section">1. 适用对象</h3><carrier-scope :value="form" :metadata="metadata" :capability="type==='capability'" @input="updateScope" /><el-form-item v-if="type==='capability'" label="仓库服务用途"><el-radio-group v-model="form.flow" @change="form.provinces=[];form.excluded_provinces=[]"><el-radio label="OUTBOUND">发货</el-radio><el-radio label="INBOUND">收货</el-radio></el-radio-group></el-form-item>
          <h3 class="form-section">2. {{type==='directory'?'快递清单条目':'快递关联'}}</h3><el-form-item v-if="type!=='directory'" label="标准快递" required><carrier-select v-model="form.standard_id" standard-only /></el-form-item>
          <template v-if="type==='directory'"><el-form-item :label="terms.code" required><el-input v-model="form.external_code" maxlength="128" placeholder="按原文填写，保留大小写、前导零和特殊字符" /></el-form-item><el-form-item :label="terms.name" required><el-input v-model="form.external_name" maxlength="200" /></el-form-item></template>
          <template v-if="type==='mapping'"><el-form-item :label="terms.item" required><el-select v-model="form.directory_id" filterable remote :remote-method="loadDirectories" @focus="loadDirectories('')"><el-option v-for="d in directories" :key="d.id" :value="d.id" :label="`${d.external_name} · ${d.external_code} · ${scopeName(d)}`" /></el-select><p class="hint">从快递清单选择已核实的编码，再与 OMS 标准快递建立关联；仓库服务能力需单独配置。</p></el-form-item><el-form-item v-if="showPreferred" :label="system==='CHANNEL'?'平台提交首选项':'仓库下发首选项'"><el-switch v-model="form.is_default" :active-value="1" :inactive-value="0" :disabled="preferredLoading"/><p class="hint">{{system==='CHANNEL'?'同用途、同范围有多个平台标识时，明确唯一的平台提交首选项。':'同范围存在多个通用输出时，仅指定一个默认输出。'}}</p><p v-if="system==='CHANNEL'&&preferredStats&&preferredStats.defaultCode" class="hint">其他关联已配置的首选标识：{{preferredStats.defaultCode}}。沿用该首选时无需开启当前项。</p></el-form-item><p v-if="preferredLoading" class="hint">正在核对提交或下发候选…</p></template>
          <el-form-item v-if="system==='WMS' && type!=='directory'" label="运输产品编码">
            <el-input v-model="form.product_code" maxlength="64" placeholder="可选；留空作为通用匹配" />
            <p class="hint">按仓库约定的运输服务编码填写。业务传入该编码时优先匹配专用配置，未命中时使用留空的通用配置。</p>
          </el-form-item>
          <template v-if="type==='capability' && form.flow==='OUTBOUND'"><el-form-item label="配送省份"><el-select v-model="form.provinces" multiple filterable :disabled="!!form.excluded_provinces.length"><el-option v-for="p in metadata.provinces||[]" :key="p" :label="p" :value="p" /></el-select></el-form-item><el-form-item label="不配送省份"><el-select v-model="form.excluded_provinces" multiple filterable :disabled="!!form.provinces.length"><el-option v-for="p in metadata.provinces||[]" :key="p" :label="p" :value="p" /></el-select></el-form-item></template>
          <h3 class="form-section">3. 来源与确认</h3><el-form-item label="配置来源与确认说明" required>
            <el-input v-model="form.evidence" type="textarea" :rows="3" maxlength="1000" show-word-limit :placeholder="configurationExample" />
            <p class="hint">填写实际核对的清单文件、版本或沟通记录，方便后续追溯。</p>
          </el-form-item>
        </template>
        <el-form-item label="状态"><el-switch v-model="form.enabled" :active-value="1" :inactive-value="0" active-text="启用" inactive-text="停用" /></el-form-item><el-form-item v-if="!form.enabled" label="停用原因" required><el-input v-model="form.disabled_reason" maxlength="500" /></el-form-item>
      </el-form><div v-if="form.id"><el-button size="small" @click="loadImpact">预览影响范围</el-button><p v-if="impact" class="hint">{{impact.message}}；相关标准 {{impact.standard_count}} 家，待发货 {{impact.waiting_shipments}} 张，待平台回传 {{impact.waiting_notifications}} 个包裹。</p></div><span slot="footer"><el-button :disabled="busy" @click="closeEditor">取消</el-button><el-button type="primary" :loading="busy" @click="save">保存配置</el-button></span>
    </el-dialog>
    <el-dialog :title="'导入'+terms.list" :visible.sync="importVisible" width="960px" append-to-body :close-on-click-modal="false">
      <el-alert v-if="importError" :title="importError" type="error" :closable="false" /><template v-if="!importResult"><el-form label-width="160px"><carrier-scope v-model="importScope" :metadata="metadata" /><el-form-item label="配置来源与确认说明" required><el-input v-model="importScope.evidence" type="textarea" :rows="3" maxlength="1000" show-word-limit :placeholder="configurationExample" /><p class="hint">填写本批快递清单的文件名、版本或核对记录；确认导入后随清单留存。</p></el-form-item><el-form-item label="UTF-8 CSV 文件"><input type="file" accept=".csv,text/csv" @change="fileChanged"><p class="hint">最多 500 行；使用文本格式保存编码，避免 Excel 去掉前导零。</p><el-button type="text" @click="downloadTemplate">下载模板</el-button></el-form-item></el-form></template>
      <template v-else><p>新增 {{count('NEW')}} 行，更新 {{count('UPDATE')}} 行，重复不变 {{count('DUPLICATE')}} 行，错误 {{count('ERROR')}} 行。确认后才写入快递清单；导入不会自动建立标准快递关联。</p><el-table :data="importResult.rows" max-height="400" size="small"><el-table-column prop="line" label="行" width="60" /><el-table-column label="结果" width="130"><template slot-scope="{row}">{{importStates[row.status]}}</template></el-table-column><el-table-column :label="terms.code" min-width="160"><template slot-scope="{row}">{{(row.data||{}).external_code}}</template></el-table-column><el-table-column :label="terms.name" min-width="160"><template slot-scope="{row}">{{(row.data||{}).external_name}}</template></el-table-column><el-table-column label="原因" min-width="220"><template slot-scope="{row}">{{row.message || (row.data||{}).disabled_reason}}</template></el-table-column></el-table></template>
      <span slot="footer"><el-button :disabled="busy" @click="importVisible=false">关闭</el-button><el-button v-if="importResult" :disabled="busy" @click="importResult=null">重新预览</el-button><el-button v-if="!importResult" type="primary" :loading="busy" :disabled="!importRows.length" @click="previewImport">检查文件并预览</el-button><el-button v-else type="primary" :loading="busy" :disabled="!!Number(importResult.errors)||importConfirmed" @click="confirmImport">{{importConfirmed?'已确认导入':'确认导入清单'}}</el-button></span>
    </el-dialog>
    <el-dialog :title="'同步'+terms.list" :visible.sync="syncVisible" width="740px" append-to-body><p>后台查询对方提供的快递清单，先预览差异，再确认导入；查询失败保留已有清单及关联。暂未接通查询接口时可导入文件。</p><el-form label-width="132px"><carrier-scope v-model="syncScope" :metadata="metadata" /></el-form><el-alert v-if="syncError" :title="syncError" type="warning" :closable="false" /><span slot="footer"><el-button @click="syncVisible=false">关闭</el-button><el-button type="primary" :loading="busy" @click="sync">提交后台查询</el-button></span></el-dialog>
    <carrier-audit ref="audit"/>
    <carrier-batch-mappings ref="batch" @changed="load"/>
    <carrier-conversion-preview ref="verification" :metadata="metadata" @checked="recordCheck"/>
    <el-dialog title="快递关联待办详情" :visible.sync="contextVisible" width="800px" append-to-body><el-descriptions v-if="contextRow" :column="1" border><el-descriptions-item label="业务单据">{{contextRow.business_sn}}</el-descriptions-item><el-descriptions-item v-for="(v,k) in context" :key="k" :label="contextLabels[k]||k">{{v}}</el-descriptions-item></el-descriptions><p class="hint">修复配置不代表业务完成。请重新校验，再重试尚未完成的动作。</p><el-button v-if="contextRow&&contextRow.state!=='COMPLETED'" type="primary" size="small" @click="repair(contextRow)">去修复当前用途的配置</el-button></el-dialog>
  </div>
</template>
<script>
import CarrierSelect from '@/components/CarrierSelect'
import CarrierCode from './CarrierCode'
import CarrierAudit from './CarrierAudit'
import { associationLabels, todoLabels, businessLabels, actionLabels, parseObject, scopeName } from '@/utils/carrierManagement'
import CarrierConversionPreview from './CarrierConversionPreview'
import CarrierBatchMappings from './CarrierBatchMappings'
import CarrierScope, { purposeLabels } from './CarrierScope'
import { carrierPage, carrierMetadata, saveCarrier, directoryPreview, directoryConfirm, directorySync, carrierTodoAction, carrierImpact, mappingOutputOptions } from '@/api/common/carriers'
import { parseCarrierCsv } from '@/utils/carrierCsv'
import { carrierTerms } from '@/utils/carrierTerms'
import { outputPreferences } from '@/utils/carrierOutputPreferences'
import { carrierMappingRule, mappingForm, mappingFlow } from '@/utils/carrierMappingPurpose'
const defaults = system => ({ id: 0, revision: 0, standard_code: '', standard_name: '', aliases: [], category: 'EXPRESS', system_type: system, provider: system==='CHANNEL'?'TMALL':'', purpose: system==='CHANNEL'?'CHANNEL_SHIPPING':'WMS_OUTBOUND_CREATE', connection_id: '', shop_id: '', owner_code: '', real_store_code: '', standard_id: '', directory_id: '', direction: 'OUT', product_code: '', is_default: 1, enabled: 1, disabled_reason: '', evidence: '', external_code: '', external_name: '', flow: 'OUTBOUND', provinces: [], excluded_provinces: [] })
export default {
  name: 'CarrierWorkspace', components: { CarrierSelect, CarrierScope, CarrierConversionPreview, CarrierBatchMappings, CarrierCode, CarrierAudit }, props: { kind: { type: String, required: true }, system: { type: String, default: 'WMS' } },
  data: () => ({ rows: [], selectedDirectories: [], impact: null, total: 0, query: { keyword:'',pageNum:1,pageSize:20,state:'',purpose:'',enabled:'',connection_id:'',shop_id:'',owner_code:'',real_store_code:'',standard_id:'',directory_id:'',external_code:'',association_state:'',business_type:'',flow:'' }, scenarioChecks:{}, listRevision:null, associations:associationLabels, businessLabels, actionLabels, metadata: {}, section: 'mapping', loading: false, error: '', epoch: 0, busy: false, editor: false, form: {}, formError: '', preferredLoading:false,preferredError:'',preferredStats:null,preferredEpoch:0,preferredTimer:null,directories: [], directoryEpoch: 0, importVisible: false, importRows: [], importScope: {}, importResult: null, importError: '', importConfirmed: false, syncVisible: false, syncScope: {}, syncError: '', auditVisible: false, auditRows: [], contextVisible: false, contextRow: null, labels: purposeLabels, sourceLabels:{MANUAL:'手工补录',IMPORT:'文件导入',API:'接口查询'}, categories: { EXPRESS: '快递', FREIGHT: '快运', OTHER: '其他' }, directions: { IN: '识别外部编码', OUT: '转换目标编码', BOTH: '双向关联' }, importStates: { NEW: '新增', UPDATE: '更新', DUPLICATE: '重复不变', ERROR: '错误' }, todoStates:todoLabels, syncStates: { PENDING: '排队查询', RUNNING: '正在查询', SUCCESS: '清单查询成功，待确认导入', FAILED: '查询失败，原配置保留', UNSUPPORTED: '尚未接通清单查询' }, contextLabels: { system_type: '外部系统', provider: '平台或WMS协议', purpose: '接口用途', connection_id: '连接实例', shop_id: '店铺身份', owner_code: '货主', real_store_code: '实体仓', external_code: '原始外部编码', raw_name: '原始快递名称', standard_id: '标准快递身份', direction: '转换方向', province: '收货省份', product_code: '运输产品' } }),
  computed: {
    terms() { return carrierTerms(this.system) },
    configurationExample() { return this.type==='capability'?'例如：已与仓库确认该快递支持当前货主、实仓及收发用途；确认记录：____。':`例如：依据${this.terms.source}提供的快递清单，已核对快递名称和编码；清单文件、版本或确认记录：____。` },
    mappingRule() { return carrierMappingRule(this.form) },
    preferredKey() { return this.editor&&this.type==='mapping'&&this.mappingRule&&this.mappingRule.direction==='OUT'&&this.form.standard_id&&(this.system!=='WMS'||this.form.connection_id)?JSON.stringify(['system_type','provider','purpose','connection_id','shop_id','owner_code','real_store_code','standard_id','product_code','id'].map(k=>this.form[k]||'')):'' },
    showPreferred() { return this.mappingRule&&this.mappingRule.direction==='OUT'&&this.preferredStats&&this.preferredStats.choices>1 },
    canAudit() { const p=this.$store.getters.permissions||[];return p.includes('*:*:*')||p.includes('common:carrier:audit') },
    filterPool() { return (this.metadata.stores||[]).filter(s=>String(s.connection_id)===this.query.connection_id) },
    filterOwners() { return this.filterPool.filter((s,i,a)=>a.findIndex(x=>x.owner_code===s.owner_code)===i) },
    filterStores() { return this.filterPool.filter(s=>s.owner_code===this.query.owner_code).filter((s,i,a)=>a.findIndex(x=>x.real_store_code===s.real_store_code)===i) },
    mapping() { return this.kind==='mapping' }, type() { return this.mapping?this.section:this.kind },
    title() { return this.kind==='standard'?'标准快递资料':this.mapping?(this.system==='CHANNEL'?'渠道快递配置':'WMS 快递配置'):this.kind==='capability'?'仓库服务能力':'快递关联待办' },
    description() { return this.kind==='standard'?'维护公司内统一的承运商身份。OMS 标准编码与外部系统编码分别保存。':this.mapping?(this.section==='directory'?this.terms.list+'记录对方提供的快递名称和编码；选择条目后可批量关联 OMS 标准快递。':this.section==='sync'?'查看快递清单的接口查询及导入结果；文件导入和手工修改可在操作记录中查询。':'将 OMS 标准快递与'+this.terms.source+'编码建立关联；业务可用性还需检查仓库服务能力。'):this.kind==='capability'?'配置具体 WMS 连接、货主与实仓的收发能力。发货配送范围不限制售后收货。':'定位阻断的业务步骤，保留实际物流事实；修复后只继续未完成动作。' },
    purposes() { return Object.keys(this.labels).filter(p => p.startsWith(this.system+'_')) },
    permission() { return this.kind==='standard'?'standardEdit':this.kind==='capability'?'capabilityEdit':this.system==='CHANNEL'?'channelEdit':'wmsEdit' },
    canEdit() { const p=this.$store.getters.permissions||[]; return p.includes('*:*:*') || p.includes('common:carrier:'+this.permission) },
    editorTitle() { return this.type==='directory'?(this.form.id?'编辑':'补录')+this.terms.item:this.type==='mapping'?(this.form.id?'编辑快递关联':'关联标准快递'):(this.form.id?'编辑':'新增')+(this.type==='standard'?'标准快递':'仓库服务能力') },
    context() { try { return JSON.parse((this.contextRow||{}).context_json || '{}') } catch (_) { return {} } }
  },
  created() { this.applyRoute();this.reload() },
  watch:{preferredKey(){this.loadPreferred()},'$route.query'(next,old){if(JSON.stringify(next)!==JSON.stringify(old)&&JSON.stringify(next)!==this.lastRoute){this.applyRoute();this.load()}}},
  beforeDestroy() { this.epoch++; this.directoryEpoch++;this.preferredEpoch++;clearTimeout(this.preferredTimer) },
  methods: {
    carrierMappingRule, mappingFlow,
    loadPreferred() {clearTimeout(this.preferredTimer);const epoch=++this.preferredEpoch;this.preferredLoading=false;this.preferredStats=null;this.preferredError='';if(!this.preferredKey)return;this.preferredLoading=true;const form={...this.form};this.preferredTimer=setTimeout(async()=>{try{const result=(await mappingOutputOptions({...form,items:[{id:form.id||0,standard_id:form.standard_id,product_code:form.product_code||''}]})).data;if(epoch!==this.preferredEpoch||!this.editor)return;const preference=outputPreferences([form],result.rows)[0];this.preferredStats=preference;this.form.is_default=preference.preferred}catch(e){if(epoch===this.preferredEpoch)this.preferredError=e.message||'提交或下发候选读取失败，请重试'}finally{if(epoch===this.preferredEpoch)this.preferredLoading=false}},250)},
    updateScope(next) { const changed=['system_type','provider','purpose','connection_id','shop_id','owner_code','real_store_code'].some(k=>next[k]!==this.form[k]);this.form=this.type==='mapping'?mappingForm(next):next;if(changed&&this.type==='mapping'){this.form.directory_id='';this.directories=[];this.loadDirectories('')} },
    async reload() { await this.load(); try { this.metadata=(await carrierMetadata()).data } catch (e) { this.error=e.message || '配置选项读取失败，请刷新重试' } },
    applyRoute() { const route=this.$route.query;this.section=['directory','sync'].includes(route.section)?route.section:'mapping';for(const key of Object.keys(this.query))this.$set(this.query,key,key==='pageNum'||key==='pageSize'?Number(route[key])|| (key==='pageNum'?1:20):String(route[key]||''));if(this.kind==='capability'&&!this.query.flow)this.query.flow='OUTBOUND' },
    remember() { const query={};for(const [key,value] of Object.entries(this.query))if(value!==''&&value!==undefined&&value!==null)query[key]=String(value);if(this.mapping)query.section=this.section;for(const key of ['from_todo','todo_sn','from_check'])if(this.$route.query[key])query[key]=this.$route.query[key];this.lastRoute=JSON.stringify(query);if(JSON.stringify(this.$route.query)!==this.lastRoute)this.$router.replace({path:this.$route.path,query}).catch(()=>{}) },
    reset() { this.query.pageNum=1;this.selectedDirectories=[];this.load() },
    clearFilters(){const flow=this.kind==='capability'?this.query.flow:'';for(const key of Object.keys(this.query))this.$set(this.query,key,key==='pageNum'?1:key==='pageSize'?20:'');this.query.flow=flow;this.load()},
    filterConnection(){this.query.owner_code='';this.query.real_store_code='';this.reset()},filterOwner(){this.query.real_store_code='';this.reset()},
    async load() { const epoch=++this.epoch;this.remember();this.loading=true;this.error='';try{const r=await carrierPage(this.type,{...this.query,...(this.mapping?{system_type:this.system}:{})});if(epoch!==this.epoch)return;if(this.listRevision!==r.data.revision){this.scenarioChecks={};this.listRevision=r.data.revision}this.rows=r.data.rows;this.total=Number(r.data.total)}catch(e){if(epoch===this.epoch){this.rows=[];this.error=e.message||'配置查询失败，请重试'}}finally{if(epoch===this.epoch)this.loading=false} },
    scopeName(row){return scopeName(row,this.metadata)},
    contextSeed(){const seed={...defaults(this.system)};for(const key of ['purpose','connection_id','shop_id','owner_code','real_store_code','standard_id','external_code','flow'])if(this.query[key])seed[key]=this.query[key];const c=(this.metadata.connections||[]).find(c=>String(c.id)===seed.connection_id);if(this.system==='WMS'&&c)seed.provider=c.provider;return seed},
    edit(row,seed) { this.form=mappingForm({...defaults(this.system),...this.contextSeed(),...(seed||{}),...(row?JSON.parse(JSON.stringify(row)):{})});this.formError='';this.impact=null;this.editor=true;this.directories=[];if(this.type==='mapping')this.loadDirectories('') },
    async associate(row){this.section='mapping';this.query.directory_id=String(row.id);this.query.purpose=row.purpose;this.query.external_code='';this.selectedDirectories=[];await this.load();this.edit(null,{...row,id:0,revision:0,standard_id:'',directory_id:row.id,evidence:'',enabled:1});this.directories=[row]},
    viewLinks(row){this.section='mapping';this.query.directory_id=String(row.id);this.query.external_code='';this.query.association_state='';this.reset()},
    moreAction(command){if(command==='sync')this.openSync();else if(command==='audit')this.$refs.audit.open();else this.reload()},
    delivery(row,full=false){if(row.flow==='INBOUND')return '支持收货，不限制发货配送省份';const list=row.provinces.length?row.provinces:row.excluded_provinces;if(!list.length)return '全国配送';const prefix=row.provinces.length?'仅配送：':'不配送：';return prefix+(full?list.join('、'):list.slice(0,2).join('、')+(list.length>2?' 等'+list.length+'省份':''))},
    todoContext(row){return parseObject(row.context_json)},
    repair(row){const context=this.todoContext(row);const capability=row.reason_code==='CAPABILITY_UNSUPPORTED';const query={...context,from_todo:String(row.id),todo_sn:row.business_sn};if(capability)query.flow=context.purpose==='WMS_OUTBOUND_CREATE'?'OUTBOUND':'INBOUND';this.contextVisible=false;this.$router.push({path:'/common-config/carriers/'+(capability?'capabilities':context.system_type==='WMS'?'wms':'channels'),query})},
    backToTodo(){this.$router.push({path:'/common-config/carriers/todos',query:{keyword:this.$route.query.todo_sn||''}})},
    recordCheck(check){this.$set(this.scenarioChecks,check.id,check)},
    closeEditor(done) { if(this.busy)return; this.editor=false; if(typeof done==='function')done() },
    async loadImpact() {try{this.impact=(await carrierImpact(this.type,this.form.id)).data}catch(e){this.formError=e.message||'影响范围查询失败'}},
    validateEditor(){
      const form=this.form;if(this.type==='standard')return !form.standard_code||!form.standard_name?'请填写标准快递编码和名称':'';
      if(this.system==='WMS'){
        if(!form.connection_id)return '请选择 WMS 连接';
        const level=form.scope_level||(form.real_store_code?'WAREHOUSE':form.owner_code?'OWNER':'CONNECTION');
        if((this.type==='capability'||level!=='CONNECTION')&&!form.owner_code)return '请选择当前范围的货主';
        if((this.type==='capability'||level==='WAREHOUSE')&&!form.real_store_code)return '请选择当前范围的实体仓';
      }else if(form.scope_level==='SHOP'&&!form.shop_id)return '请选择指定店铺';else if(form.scope_level==='CONNECTION'&&!form.connection_id)return '请选择指定接入应用';
      if(this.type==='directory')return !form.external_code||!form.external_name?'请填写快递编码和名称':'';
      if(!form.standard_id)return '请选择标准快递';if(this.type==='mapping'&&!form.directory_id)return '请选择快递清单中的对应条目';return '';
    },
    async save() { if(this.busy)return;const validation=this.validateEditor();if(validation){this.formError=validation;return;}if(this.type!=='standard'&&!String(this.form.evidence||'').trim()){this.formError='请填写配置来源与确认说明';return;}if(this.preferredKey&&(this.preferredLoading||this.preferredError||!this.preferredStats)){this.formError=this.preferredError||'请等待提交或下发候选核对完成';return;} this.busy=true; this.formError=''; try { const r=await saveCarrier(this.type,this.type==='mapping'?mappingForm(this.form):this.form); this.editor=false;this.scenarioChecks={}; if((r.data.warnings||[]).length)this.$message.warning(r.data.warnings.join('；'));else this.$message.success('配置已保存'); await this.load() } catch(e) { this.formError=e.message||'保存失败，请核对后重试' } finally { this.busy=false } },
    async loadDirectories(keyword) { const epoch=++this.directoryEpoch; try { const r=await carrierPage('directory',{system_type:this.system,provider:this.form.provider,purpose:this.form.purpose,keyword,pageSize:100,for_mapping:'1',owner_code:this.form.owner_code||'',real_store_code:this.form.real_store_code||'',connection_id:this.form.connection_id||'',shop_id:this.form.shop_id||''}); if(epoch===this.directoryEpoch){const selected=this.directories.find(d=>d.id===this.form.directory_id);this.directories=r.data.rows;if(!selected&&this.form.directory_id&&!this.directories.some(d=>d.id===this.form.directory_id)){const chosen=(await carrierPage('directory',{record_id:this.form.directory_id,pageSize:1})).data.rows;if(epoch!==this.directoryEpoch)return;this.directories.push(...chosen)}if(selected&&!this.directories.some(d=>d.id===selected.id))this.directories.unshift(selected);if(!this.form.directory_id&&this.form.external_code){const exact=this.directories.filter(d=>d.external_code===this.form.external_code);if(exact.length===1)this.form.directory_id=exact[0].id}} } catch(e) { if(epoch===this.directoryEpoch)this.formError=e.message||'快递清单读取失败' } },
    openImport() { this.importScope=this.contextSeed(); this.importRows=[]; this.importResult=null; this.importError=''; this.importConfirmed=false; this.importVisible=true },
    async fileChanged(event) { this.importError=''; try { const file=event.target.files[0]; if(!file)return; if(file.size>1024*1024)throw new Error('文件不能超过 1MB');this.importRows=parseCarrierCsv(await file.text()) } catch(e) { this.importRows=[];this.importError=e.message } },
    downloadTemplate() { const blob=new Blob(['\uFEFFexternal_code,external_name,enabled,disabled_reason\r\n"TEST-001","测试承运商",1,\r\n'],{type:'text/csv;charset=utf-8'});const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=this.terms.list+'导入模板.csv';a.click();URL.revokeObjectURL(url) },
    async previewImport() { if(!String(this.importScope.evidence||'').trim()){this.importError='请填写配置来源与确认说明';return;}this.busy=true;this.importError='';try {this.importResult=(await directoryPreview({...this.importScope,rows:this.importRows})).data} catch(e) {this.importError=e.message||'文件检查失败'} finally {this.busy=false} },
    count(status) { return (this.importResult.rows||[]).filter(r=>r.status===status).length },
    async confirmImport() { if(this.busy||this.importConfirmed)return;this.busy=true;try {await directoryConfirm(this.importResult.request_key);this.importConfirmed=true;this.$message.success('清单已导入，请继续关联标准快递');await this.load()} catch(e) {this.importError=e.message||'确认失败'} finally {this.busy=false} },
    openSync() {this.syncScope=this.contextSeed();this.syncError='';this.syncVisible=true},
    async sync() {this.busy=true;try {const r=(await directorySync(this.syncScope)).data;this.syncError=r.message;if(r.state==='PENDING'){this.syncVisible=false;this.section='sync';await this.load();this.$message.success('后台查询已排队')}} catch(e) {this.syncError=e.message||'提交失败'} finally {this.busy=false}},
    syncMessage(row) {try {const r=JSON.parse(row.result_json);return r.message||`快递清单已核实 ${r.rows.length} 行，等待人工确认`}catch(_){return '请查看清单更新记录'}},
    showSync(row) {try {this.importResult=JSON.parse(row.result_json);this.importConfirmed=false;this.importError='';this.importVisible=true}catch(_){this.error='快递清单结果无法解析'}},
    async todoAction(row,action) {if(this.busy)return;this.busy=true;try {const r=(await carrierTodoAction(row.id,action,row.revision)).data;this.$message.info(r.message||'已核对');await this.load()} catch(e) {this.error=e.message||'处理失败，请刷新核对'} finally {this.busy=false}},
    configure(row) {this.contextRow=row;this.contextVisible=true},
    openBusiness(row) { const paths={SHIPMENT:'/oms-order/shipments',REFUND:'/oms-order/refunds',EXCHANGE:'/oms-order/exchanges',PURCHASE_RETURN:'/oms-supplychain/purchaseReturns',RECLAIM:'/oms-supplychain/purchaseReturns'};this.$router.push({path:paths[row.business_type]||'/oms-order/business',query:row.business_type==='PURCHASE_RETURN'?{return_sn:row.business_sn,id:row.business_id}:row.business_type==='RECLAIM'?{reclaimId:row.business_id}:{number:row.business_sn,open:row.business_id}}) },

  }
}
</script>
