.workspace-tools{display:flex;justify-content:space-between;gap:16px;flex-wrap:wrap;align-items:flex-start;margin-top:18px}.toolbar{margin:0;flex:1;min-width:380px}.toolbar>.el-input{width:230px}.toolbar>.el-select{width:175px}.page-actions{display:flex;gap:8px;flex-wrap:wrap}.page-actions .el-button+.el-button{margin-left:0}.scope-filters{display:flex;flex-wrap:wrap;gap:10px;margin-top:12px;padding:12px;background:#f7f9fc;border-radius:6px}.scope-filters>.el-select{width:205px}.selection-bar{padding:12px;background:#edf4ff;display:flex;gap:16px;align-items:center;margin-top:12px}.table-caption{font-size:12px;color:#788596;margin:20px 0 10px}.table-caption span{margin-left:10px}.truncate{display:block;white-space:nowrap;text-overflow:ellipsis;overflow:hidden}.scope-text{display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;overflow:hidden}.warning{font-size:12px;color:#b97916}.form-section{font-size:14px;color:#344761;border-bottom:1px solid #e8edf3;padding-bottom:10px;margin:18px 0}.source-proof{white-space:pre-wrap;overflow-wrap:anywhere}.flow-tabs{margin:8px 0}.carriers>>>.el-table .cell{line-height:1.8}.carriers>>>.el-table td{padding:12px 0}
